\begin{ex}%[9H5N4-1]
\immini[thm]{
Cho $\Delta{FME}$ vuông tại ${E}$. Khi đó ${FE}$ là tiếp tuyến của đường tròn nào sau đây? 

\choice
{  Đường tròn $(F,ME)$ }
   {  Đường tròn $(E,ME)$  }
     { \True  Đường tròn $(M,ME)$ }
    {  Đường tròn đường kính ${FM}$  }
}{
\begin{tikzpicture}
        % Tọa độ cho tam giác vuông
        \coordinate (P) at (0, 0);
        \coordinate (M) at (4, 0);
        \coordinate (N) at (0, 3);

        % Vẽ các cạnh của tam giác
        \draw[thick] (M) -- (N) -- (P) -- cycle;

        % Ghi nhãn các điểm
        \node[below left] at (P) {$E$};
        \node[below right] at (M) {$F$};
        \node[above left] at (N) {$M$};

        % Vẽ dấu vuông tại điểm A
        \draw (0,0) rectangle +(0.3,0.3);
    \end{tikzpicture}
}
\loigiai{
Tam giác vuông có hai cạnh góc vuông vuông góc với nhau tại đỉnh góc vuông nên cạnh thứ nhất đi qua tiếp điểm và vuông góc với bán kính là cạnh còn lại. Do đó Đường tròn $(M,ME)$.
}\end{ex}

